.pc-venta-cliente-buscador{position:relative}.pc-venta-item-resultados{position:absolute;z-index:1080;background:#fff;border:1px solid #eee2c8;border-radius:8px;width:100%;max-height:220px;overflow-y:auto;box-shadow:0 6px 18px rgba(0,0,0,.08);display:none}.pc-venta-item-resultados button{width:100%;padding:8px 10px;cursor:pointer;font-size:.85rem;border:0;border-bottom:1px dashed #f0ead9;background:#fff;text-align:left}.pc-venta-item-resultados button:hover{background:#fdf6e3}.pc-venta-item-resultados .disp{color:#8a8578;font-size:.8em}
#modalDespacho{z-index:1055}#modalClienteDespacho{z-index:1070}body.modal-open #modalDespacho.show~.modal-backdrop{z-index:1050}body.modal-open .modal-backdrop.tr-backdrop-cliente{z-index:1065}
.tr-total{background:#f8fafc;border-radius:10px;padding:12px;text-align:right;font-weight:800}.tr-state{font-weight:700;font-size:.8rem;border-radius:99px;padding:4px 8px;background:#fff4d6;color:#9a6500}.tr-state.E{background:#e8f7ee;color:#16804a}.tr-state.R{background:#ffeded;color:#b42318}
