<div class="modal fade" id="modalClienteDespacho" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="formClienteDespacho"><div class="modal-header"><h5 class="modal-title">Registrar cliente</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="mb-2"><label class="form-label">RUC / DNI *</label><input type="text" class="form-control" id="nuevo_cliente_dni" maxlength="11" inputmode="numeric" required><div class="form-text">8 dígitos (DNI) u 11 dígitos (RUC).</div></div><div class="mb-2"><label class="form-label">Razón social / Nombre completo *</label><input type="text" class="form-control" id="nuevo_cliente_nombre" required></div><div class="mb-2"><label class="form-label">Nombre comercial</label><input type="text" class="form-control" id="nuevo_cliente_comercial"></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button type="submit" class="btn btn-primary">Guardar cliente</button></div></form></div></div></div>
<div class="modal fade" id="modalDespacho" tabindex="-1"><div class="modal-dialog modal-xl"><form class="modal-content" id="formDespacho"><div class="modal-header"><div><h5 class="modal-title">Agregar despacho al viaje</h5><div id="despachoViajeLabel" class="tr-muted"></div></div><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" id="despacho_viaje_id"><div class="row g-2 mb-3"><div class="col-md-4 pc-venta-cliente-buscador"><label class="form-label">Cliente <span class="text-muted fw-normal">(opcional)</span></label><input type="text" class="form-control" id="despacho_cliente_texto" placeholder="Buscar cliente por nombre o RUC/DNI..." autocomplete="off"><div class="pc-venta-item-resultados" id="despacho_cliente_resultados"></div><input type="hidden" id="despacho_cliente_ruc" value="99999999"><div class="d-flex align-items-center gap-2 mt-1 flex-wrap"><div class="form-text m-0" id="despacho_cliente_seleccionado">Cliente: Clientes Varios · RUC/DNI: 99999999</div><button type="button" class="btn btn-sm btn-outline-primary" onclick="abrirRegistroClienteDespacho()"><i class="fa-solid fa-user-plus"></i> Registrar cliente</button></div></div><div class="col-md-2"><label class="form-label">Fecha *</label><input class="form-control" type="date" id="despacho_fecha" required></div><div class="col-md-2"><label class="form-label">Moneda *</label><select class="form-select" id="despacho_moneda" required></select></div><div class="col-md-2" id="despacho_tc_fuente_wrap"><label class="form-label">Tipo de cambio</label><select class="form-select" id="despacho_tc_fuente"><option value="oficial">Oficial · API</option><option value="calle">De calle</option></select></div><div class="col-md-2" id="despacho_tc_wrap"><label class="form-label">Tipo de cambio (S/ por unidad)</label><input class="form-control" type="number" min="0.0001" step="0.0001" id="despacho_tc" value="1"></div><div class="col-12"><small id="despacho_tc_info" class="text-muted"></small></div></div><div class="mb-2"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2"><strong>Productos</strong><div class="tr-qr-tools"><input type="search" class="form-control form-control-sm" id="despacho_buscar_producto" placeholder="Buscar producto..."><button type="button" class="btn btn-sm btn-outline-primary" onclick="escanearPaqueteDespacho()"><i class="fa-solid fa-qrcode"></i> Escanear QR del paquete</button></div></div><div id="despachoProductosCards" class="tr-product-grid"></div><div class="form-text">Toca una tarjeta para agregar el producto. Al escanear un paquete se cargan su producto y bulto; confirma la cantidad y el precio en soles.</div></div><div id="despachoLineas"></div><div class="row justify-content-end mt-3"><div class="col-md-4"><label class="form-label">Descuento general en soles (opcional)</label><input class="form-control" type="number" min="0" step="0.01" id="despacho_descuento" placeholder="Sin descuento" value=""><div class="form-text">Déjalo vacío si no corresponde descuento.</div></div><div class="col-md-4"><div class="tr-total mt-4" id="despachoTotal">Total base en soles: S/ 0.00</div></div></div><div class="form-text mt-2">Precios y descuentos en soles. La moneda seleccionada solo convierte el total a cobrar. No afecta Punto de Venta ni descuenta inventario.</div></div><div class="modal-footer"><button class="btn btn-secondary" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary" type="submit">Guardar despacho</button></div></form></div></div>

<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><script src="assets/js/qr-camera.js?v=20261114"></script>
<script>
const TR_API='controllers/clssTransporte.php';let trTab='vehiculos',trDatos={transportes:[],clientes:[],monedas:[],productos:[]},trViajes=[],trDespachos=[],trDetalles=[],tcOficialDespacho=null;
const trModalVeh=new bootstrap.Modal(document.getElementById('modalTransporte')),trModalViaje=new bootstrap.Modal(document.getElementById('modalViaje')),trModalDesp=new bootstrap.Modal(document.getElementById('modalDespacho')),trModalCliente=new bootstrap.Modal(document.getElementById('modalClienteDespacho'));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function trCall(accion,data={}){const r=await fetch(TR_API,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams({accion,...data})});const j=await r.json();if(!j.success)throw Error(j.message||'Error');return j}
const msg=(title,text,icon='error')=>Swal.fire({title,text,icon});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{trTab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));document.getElementById('btnPrincipal').innerHTML=trTab==='vehiculos'?'<i class="fa-solid fa-plus"></i> Nuevo transporte':'<i class="fa-solid fa-plus"></i> Nuevo viaje';document.getElementById('trBuscar').placeholder=trTab==='vehiculos'?'Buscar vehículo por nombre o placa':'Buscar por placa o transportista';document.getElementById('trEstadoFiltro').style.display=trTab==='vehiculos'?'':'none';renderTransporte()});
document.getElementById('trBuscar').addEventListener('input',renderTransporte);document.getElementById('trEstadoFiltro').addEventListener('change',cargarTransportes);
async function cargarTodo(){try{await Promise.all([cargarTransportes(),cargarDatosDespacho(),cargarViajes()])}catch(e){msg('No se pudo cargar',e.message)}}
async function cargarTransportes(){const j=await trCall('LISTARTRANSPORTES',{texto:document.getElementById('trBuscar').value,estado:document.getElementById('trEstadoFiltro').value});trDatos.transportes=j.transportes;renderTransporte()}
async function cargarDatosDespacho(){const j=await trCall('LISTARDATOSDESPACHO');trDatos={...trDatos,...j};llenarSelectsDespacho()}
async function cargarViajes(){const j=await trCall('LISTARVIAJES');trViajes=j.viajes;trDespachos=j.despachos;trDetalles=j.detalles;renderTransporte()}
function accionPrincipal(){trTab==='vehiculos'?abrirVehiculo():abrirViaje()}
function renderTransporte(){const c=document.getElementById('trContenido');if(trTab==='vehiculos'){const q=document.getElementById('trBuscar').value.toLowerCase();const rows=(trDatos.transportes||[]).filter(x=>(`${x.nombre} ${x.placa||''}`).toLowerCase().includes(q));c.innerHTML=rows.length?`<div class="table-responsive"><table class="pc-table"><thead><tr><th>Vehículo</th><th>Placa</th><th>Capacidad</th><th>Estado</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.nombre)}</b></td><td>${esc(x.placa||'—')}</td><td>${x.capacidad_carga?`${esc(x.capacidad_carga)} kg`:'—'}</td><td>${x.deleted_at?'Inactivo':'Activo'}</td><td>${x.deleted_at?'':`<button class="btn btn-sm btn-outline-primary" onclick="editarVehiculo(${Number(x.id)})">Editar</button> <button class="btn btn-sm btn-outline-danger" onclick="borrarVehiculo(${Number(x.id)})">Desactivar</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<div class="tr-muted p-3">No hay vehículos para mostrar.</div>';return;}const q=document.getElementById('trBuscar').value.toLowerCase();const viajes=(trViajes||[]).filter(v=>`${v.transporte_nombre} ${v.placa} ${JSON.stringify(v.js_transportistas)}`.toLowerCase().includes(q));c.innerHTML=viajes.length?`<div class="tr-grid">${viajes.map(v=>renderViaje(v)).join('')}</div>`:'<div class="tr-muted p-3">No hay viajes registrados.</div>'}
function renderViaje(v){const drivers=parseJson(v.js_transportistas),stops=parseJson(v.js_ubicaciones_ruta),sales=trDespachos.filter(s=>Number(s.movimiento_transporte_id)===Number(v.id)),cerrado=sales.length>0&&sales.every(s=>s.estado!=='C');return `<article class="tr-card"><div class="d-flex justify-content-between gap-2"><div><h3>${esc(v.transporte_nombre||'Vehículo')} ${v.placa?`· ${esc(v.placa)}`:''}</h3><div class="tr-muted">Viaje #${v.id} · ${esc(v.fecha_translado)} · ${v.capacidad_carga?`${esc(v.capacidad_carga)} kg`:''}</div></div><span class="tr-state ${cerrado?'E':'C'}">${cerrado?'Despachos cerrados':'En ruta'}</span></div><div class="mt-2"><b>Transportistas</b><br>${drivers.map(d=>`<span class="tr-chip">${esc(typeof d==='string'?d:d.nombre||'')}</span>`).join('')||'—'}</div><div class="mt-2"><b>Ruta</b>${stops.map(s=>`<div class="tr-stop">${esc(typeof s==='string'?s:s.ubicacion||s.nombre||'')}</div>`).join('')||'<div class="tr-stop">—</div>'}</div><div class="d-flex justify-content-between mt-2"><span class="tr-muted">${sales.length} despacho(s)</span><b>S/ ${Number(v.monto_total).toFixed(2)} total base</b></div><div class="d-flex flex-wrap gap-2 mt-3"><button class="btn btn-sm btn-primary" onclick="abrirDespacho(${Number(v.id)},'${esc(v.transporte_nombre||'')}')">+ Despacho</button><button class="btn btn-sm btn-outline-primary" onclick="editarViaje(${Number(v.id)})">Editar viaje</button><button class="btn btn-sm btn-outline-danger" onclick="borrarViaje(${Number(v.id)})">Eliminar</button></div>${sales.map(s=>renderDespacho(s)).join('')}</article>`}
function renderDespacho(s){const lines=trDetalles.filter(x=>x.registro_uid===s.registro_uid);const uid=String(s.registro_uid||'');const fuente=s.tipo_cambio_fuente==='oficial'?'oficial API':s.tipo_cambio_fuente==='calle'?'tipo de calle':'local';const totalPEN=Number(s.monto_total_pen??s.monto)||0;const totalCobro=Number(s.monto_total_cobro??s.monto)||0;return `<div class="border-top mt-3 pt-2"><div class="d-flex justify-content-between align-items-start gap-2"><div><b>${esc(s.cliente)}</b><div class="tr-muted">Despacho ${esc(uid.slice(0,8))} · ${esc(s.fecha_venta)} · Base: S/ ${totalPEN.toFixed(2)} · Cobro: ${esc(s.moneda)} ${totalCobro.toFixed(2)}</div><div class="tr-muted">Cambio ${esc(fuente)}: ${Number(s.tipo_cambio_aplicado||1).toFixed(4)} · ${esc(s.fecha_tipo_cambio||s.fecha_venta)}</div></div><select class="form-select form-select-sm" style="max-width:150px" onchange="estadoDespacho('${uid}',this.value)"><option value="C" ${s.estado==='C'?'selected':''}>En camino</option><option value="E" ${s.estado==='E'?'selected':''}>Entregado</option><option value="R" ${s.estado==='R'?'selected':''}>Rechazado</option></select></div>${lines.map(l=>`<div class="tr-muted">${esc(l.producto)} · ${esc(l.cantidad)} ${esc(l.unidad_venta_corto||'')} · S/ ${Number(l.sub_total_calcular).toFixed(2)}</div>`).join('')}</div>`}
function parseJson(x){try{const v=typeof x==='string'?JSON.parse(x):x;return Array.isArray(v)?v:[]}catch{return[]}}
function abrirVehiculo(x=null){document.getElementById('formTransporte').reset();document.getElementById('transporte_id').value=x?.id||'';document.getElementById('tituloTransporte').textContent=x?'Editar transporte':'Nuevo transporte';if(x){transporte_nombre.value=x.nombre;transporte_placa.value=x.placa||'';transporte_capacidad.value=x.capacidad_carga||''}trModalVeh.show()}
function editarVehiculo(id){abrirVehiculo(trDatos.transportes.find(x=>Number(x.id)===id))}
document.getElementById('formTransporte').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));await trCall('GUARDARTRANSPORTE',d);trModalVeh.hide();await Promise.all([cargarTransportes(),cargarDatosDespacho()]);msg('Guardado','Transporte actualizado correctamente.','success')}catch(e){msg('No se pudo guardar',e.message)}};
async function borrarVehiculo(id){const a=await Swal.fire({title:'¿Desactivar vehículo?',icon:'warning',showCancelButton:true,confirmButtonText:'Desactivar',cancelButtonText:'Cancelar'});if(!a.isConfirmed)return;try{await trCall('ELIMINARTRANSPORTE',{id});await cargarTransportes()}catch(e){msg('No se pudo desactivar',e.message)}}
function fillOptions(id,rows,value,label,first){document.getElementById(id).innerHTML=`<option value="">${first}</option>`+rows.map(x=>`<option value="${esc(x[value])}">${esc(label(x))}</option>`).join('')}
function llenarSelectsDespacho(){fillOptions('viaje_transporte',trDatos.transportes,'id',x=>`${x.nombre}${x.placa?' · '+x.placa:''}`,'Selecciona vehículo');fillOptions('despacho_moneda',trDatos.monedas,'id',x=>`${x.codigo} (${x.simbolo})`,'Selecciona moneda');renderProductosDespacho()}
function abrirViaje(v=null){document.getElementById('formViaje').reset();document.getElementById('viaje_id').value=v?.id||'';document.getElementById('tituloViaje').textContent=v?'Editar viaje':'Nuevo viaje';viaje_fecha.value=v?.fecha_translado||new Date().toISOString().slice(0,10);if(v){viaje_transporte.value=v.transporte_id;viaje_transportistas.value=parseJson(v.js_transportistas).map(x=>typeof x==='string'?x:x.nombre||'').join('\n');viaje_ruta.value=parseJson(v.js_ubicaciones_ruta).map(x=>typeof x==='string'?x:x.ubicacion||'').join('\n')}trModalViaje.show()}
function editarViaje(id){const v=trViajes.find(x=>Number(x.id)===id);if(v)abrirViaje(v)}
document.getElementById('formViaje').onsubmit=async e=>{e.preventDefault();const lines=id=>document.getElementById(id).value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);try{await trCall('GUARDARVIAJE',{id:viaje_id.value,transporte_id:viaje_transporte.value,fecha_translado:viaje_fecha.value,js_transportistas:JSON.stringify(lines('viaje_transportistas')),js_ubicaciones_ruta:JSON.stringify(lines('viaje_ruta'))});trModalViaje.hide();await cargarViajes();msg('Guardado','Viaje registrado.','success')}catch(e){msg('No se pudo guardar',e.message)}};
async function borrarViaje(id){const a=await Swal.fire({title:'¿Eliminar viaje?',text:'Solo se puede eliminar si aún no tiene despachos.',icon:'warning',showCancelButton:true,confirmButtonText:'Eliminar',cancelButtonText:'Cancelar'});if(!a.isConfirmed)return;try{await trCall('ELIMINARVIAJE',{id});await cargarViajes()}catch(e){msg('No se pudo eliminar',e.message)}}
function abrirDespacho(id,nombre){document.getElementById('formDespacho').reset();tcOficialDespacho=null;despacho_viaje_id.value=id;despachoViajeLabel.textContent=`Viaje #${id} · ${nombre}`;despacho_cliente_texto.value='';despacho_cliente_ruc.value='99999999';despacho_cliente_seleccionado.textContent='Cliente: Clientes Varios · RUC/DNI: 99999999';despacho_cliente_resultados.style.display='none';despacho_fecha.value=new Date().toISOString().slice(0,10);despacho_moneda.value=String(trDatos.monedas.find(m=>m.codigo==='PEN')?.id||'');despacho_tc_fuente.value='oficial';despacho_tc.value='1';despacho_descuento.value='';despachoLineas.innerHTML='';despacho_buscar_producto.value='';renderProductosDespacho();trModalDesp.show();actualizarTipoCambioDespacho({resetManual:true}).then(calcularDespacho)}
async function actualizarTipoCambioDespacho({resetManual=false}={}){const moneda=trDatos.monedas.find(m=>String(m.id)===String(despacho_moneda.value))?.codigo||'PEN';const fuente=document.getElementById('despacho_tc_fuente').value;const fuenteWrap=document.getElementById('despacho_tc_fuente_wrap'),tcWrap=document.getElementById('despacho_tc_wrap'),campo=document.getElementById('despacho_tc'),info=document.getElementById('despacho_tc_info');if(moneda==='PEN'){fuenteWrap.hidden=true;tcWrap.hidden=true;campo.value='1';campo.disabled=true;info.textContent='PEN: no requiere tipo de cambio.';return}fuenteWrap.hidden=false;tcWrap.hidden=false;campo.disabled=fuente==='oficial';campo.readOnly=false;if(fuente==='oficial')info.textContent='Consultando tipo de cambio oficial de Chequea…';else if(tcOficialDespacho&&tcOficialDespacho.moneda===moneda){if(resetManual||!campo.value||campo.dataset.moneda!==moneda)campo.value=Number(tcOficialDespacho.venta).toFixed(4);campo.dataset.moneda=moneda;info.textContent=`Cambio de calle manual. Referencia oficial ${moneda}: compra ${Number(tcOficialDespacho.compra).toFixed(4)} / venta ${Number(tcOficialDespacho.venta).toFixed(4)} (${tcOficialDespacho.fecha}).`}else info.textContent='Ingresa el tipo de cambio de calle acordado.';if(fuente==='calle'&&tcOficialDespacho?.moneda===moneda)return;try{const r=await trCall('CONSULTARTIPOCAMBIO',{fecha:despacho_fecha.value,moneda});if(!r.success)throw Error(r.message||'No se pudo consultar el tipo de cambio oficial.');tcOficialDespacho={...r.tipo_cambio,moneda};if(fuente==='oficial'){campo.value=Number(tcOficialDespacho.venta).toFixed(4);campo.dataset.moneda=moneda;info.textContent=`${moneda} · compra ${Number(tcOficialDespacho.compra).toFixed(4)} / venta ${Number(tcOficialDespacho.venta).toFixed(4)} (${tcOficialDespacho.fecha}). Fuente oficial: Chequea API.`}else{if(resetManual||!campo.value||campo.dataset.moneda!==moneda)campo.value=Number(tcOficialDespacho.venta).toFixed(4);campo.dataset.moneda=moneda;info.textContent=`Cambio de calle manual. Referencia oficial ${moneda}: compra ${Number(tcOficialDespacho.compra).toFixed(4)} / venta ${Number(tcOficialDespacho.venta).toFixed(4)} (${tcOficialDespacho.fecha}).`}}catch(e){if(fuente==='oficial'){campo.value='';info.textContent=`${e.message} Cambia a “De calle” para registrar una tasa manual.`}else info.textContent=`No se pudo consultar la referencia oficial. Ingresa la tasa de calle acordada. ${e.message}`}}
document.getElementById('despacho_moneda').addEventListener('change',()=>{tcOficialDespacho=null;despacho_tc.value='';actualizarTipoCambioDespacho({resetManual:true}).then(calcularDespacho)});document.getElementById('despacho_fecha').addEventListener('change',()=>{tcOficialDespacho=null;despacho_tc.value='';actualizarTipoCambioDespacho({resetManual:true}).then(calcularDespacho)});document.getElementById('despacho_tc_fuente').addEventListener('change',()=>actualizarTipoCambioDespacho({resetManual:true}).then(calcularDespacho));
function renderProductosDespacho(){const cont=document.getElementById('despachoProductosCards');if(!cont)return;const q=(document.getElementById('despacho_buscar_producto')?.value||'').trim().toLocaleLowerCase('es');const productos=trDatos.productos.filter(p=>`${p.codigo||''} ${p.descripcion||''}`.toLocaleLowerCase('es').includes(q));cont.innerHTML=productos.length?productos.map(p=>`<button type="button" class="tr-product-card" onclick="agregarLineaDespacho(${Number(p.id)})"><strong>${esc(p.codigo)} · ${esc(p.descripcion)}</strong><small class="tr-stock">Stock actual: ${Number(p.stock||0).toLocaleString('es-PE',{maximumFractionDigits:2})} ${esc(p.unidad||'UND')}</small><small>Unidad de venta: ${esc(p.unidad||'UND')}</small></button>`).join(''):'<div class="tr-muted">No hay productos que coincidan.</div>'}
document.getElementById('despacho_buscar_producto').addEventListener('input',renderProductosDespacho);
function agregarLineaDespacho(productoId,paquete=null){const p=trDatos.productos.find(x=>Number(x.id)===Number(productoId));if(!p)return;const row=document.createElement('div');row.className='tr-line';row.innerHTML=`<div class="tr-product-wrap"><input type="hidden" class="tr-product" value="${Number(p.id)}"><div class="tr-line-product">${esc(p.codigo)} · ${esc(p.descripcion)}</div><div class="tr-product-info">Stock actual: <b>${Number(p.stock||0).toLocaleString('es-PE',{maximumFractionDigits:2})} ${esc(p.unidad||'UND')}</b> · Unidad de venta: <b>${esc(p.unidad||'UND')}</b>${paquete?`<br>Paquete #${Number(paquete.empaquetado_id)}: ${Number(paquete.cantidad_disponible_paquete).toLocaleString('es-PE',{maximumFractionDigits:2})} ${esc(paquete.unidad_paquete||'UND')} disponibles · QR validado.`:''}</div></div><input class="form-control form-control-sm tr-qty" type="number" min="0.01" step="0.01" placeholder="Cantidad (${esc(p.unidad||'UND')})" required><input class="form-control form-control-sm tr-price" type="number" min="0" step="0.01" placeholder="Precio unitario (S/)" required><input class="form-control form-control-sm tr-disc" type="number" min="0" step="0.01" value="" placeholder="Desc. S/ opcional" title="Descuento opcional de esta línea; déjalo vacío si no hay descuento"><input class="form-control form-control-sm tr-pack" type="number" min="1" step="1" placeholder="ID bulto" value="${paquete?Number(paquete.empaquetado_id):''}" ${paquete?'readonly title="Vinculado al QR escaneado"':''}><button class="btn btn-sm btn-outline-danger tr-remove" type="button" title="Quitar" onclick="this.parentElement.remove();calcularDespacho()">×</button>`;row.querySelectorAll('input').forEach(el=>el.addEventListener('input',calcularDespacho));document.getElementById('despachoLineas').appendChild(row);if(paquete)row.querySelector('.tr-qty').focus();calcularDespacho()}
async function escanearPaqueteDespacho(){const codigo=await new Promise(resolve=>window.abrirLectorQR(resolve));if(!codigo)return;try{const r=await trCall('BUSCARPAQUETEQR',{codigo_qr:codigo});const p=r.paquete;if(document.querySelector(`#despachoLineas .tr-pack[value="${Number(p.empaquetado_id)}"]`)){msg('Paquete ya agregado',`El bulto #${p.empaquetado_id} ya está en este despacho.`,'info');return}const producto=trDatos.productos.find(x=>Number(x.id)===Number(p.producto_id));if(!producto)throw Error('El producto del paquete está inactivo o no aparece disponible.');agregarLineaDespacho(p.producto_id,p);msg('QR leído','Se cargó el producto y se vinculó el paquete. Ingresa la cantidad en unidad de venta y el precio en soles.','success')}catch(e){msg('No se pudo cargar el QR',e.message)}}
function calcularDespacho(){let total=0;document.querySelectorAll('#despachoLineas .tr-line').forEach(r=>{total+=(Number(r.querySelector('.tr-qty').value)||0)*(Number(r.querySelector('.tr-price').value)||0)-(Number(r.querySelector('.tr-disc').value)||0)});total=Math.max(0,total-(Number(despacho_descuento.value)||0));const moneda=trDatos.monedas.find(m=>String(m.id)===String(despacho_moneda.value));const codigo=moneda?.codigo||'PEN';const tc=codigo==='PEN'?1:(Number(despacho_tc.value)||0);const cobro=tc>0?(codigo==='PEN'?total:total/tc):null;document.getElementById('despachoTotal').textContent=`Total base en soles: S/ ${total.toFixed(2)}${cobro===null?' · Esperando tipo de cambio':codigo==='PEN'?'':` · Cobro estimado: ${moneda?.simbolo||codigo} ${cobro.toFixed(2)} ${codigo}`}`}
despacho_descuento.addEventListener('input',calcularDespacho);
despacho_tc.addEventListener('input',calcularDespacho);
document.getElementById('formDespacho').onsubmit=async e=>{e.preventDefault();const items=[...document.querySelectorAll('#despachoLineas .tr-line')].map(r=>({producto_id:r.querySelector('.tr-product').value,cantidad:r.querySelector('.tr-qty').value,precio:r.querySelector('.tr-price').value,descuento:r.querySelector('.tr-disc').value,empaquetado_id:r.querySelector('.tr-pack').value}));const textoCliente=despacho_cliente_texto.value.trim();if(textoCliente&&!despacho_cliente_ruc.value){msg('Selecciona un cliente','Elige un cliente de la lista de resultados o deja el campo vacío para usar Clientes Varios.','warning');return}const clienteRuc=despacho_cliente_ruc.value||'99999999',clienteNombre=textoCliente||'Clientes Varios';try{await trCall('GUARDARDESPACHO',{movimiento_transporte_id:despacho_viaje_id.value,cliente_ruc:clienteRuc,cliente:clienteNombre,moneda_id:despacho_moneda.value,fecha_venta:despacho_fecha.value,fuente_tipo_cambio:despacho_tc_fuente.value,tipo_cambio:despacho_tc.value,descuento_general:despacho_descuento.value,items:JSON.stringify(items)});trModalDesp.hide();await cargarViajes();msg('Despacho guardado','Se agregó al viaje sin afectar Punto de Venta ni stock.','success')}catch(e){msg('No se pudo guardar',e.message)}};
async function estadoDespacho(registro_uid,estado){try{await trCall('CAMBIARESTADODESPACHO',{registro_uid,estado});await cargarViajes()}catch(e){msg('No se pudo actualizar',e.message)}}
document.addEventListener('blur',event=>{const input=event.target;if(input instanceof HTMLInputElement&&input.type==='number'&&input.value!==''){const value=Number(input.value);if(Number.isFinite(value))input.value=String(value)}},true);
document.addEventListener('DOMContentLoaded',cargarTodo);
</script>
<script>
let clientesDespachoResultados=[];let clienteDespachoTimer=null;
document.getElementById('despacho_cliente_texto').addEventListener('input',function(){const texto=this.value.trim(),box=document.getElementById('despacho_cliente_resultados');document.getElementById('despacho_cliente_ruc').value='';document.getElementById('despacho_cliente_seleccionado').textContent='Cliente: Clientes Varios · RUC/DNI: 99999999';clearTimeout(clienteDespachoTimer);if(texto.length<2){box.style.display='none';return}clienteDespachoTimer=setTimeout(()=>{clientesDespachoResultados=trDatos.clientes.filter(c=>`${c.razon_social||''} ${c.nombre_comercial||''} ${c.ruc||''}`.toLocaleLowerCase('es').includes(texto.toLocaleLowerCase('es'))).slice(0,15);box.innerHTML=clientesDespachoResultados.map((c,i)=>`<button type="button" data-cliente-index="${i}"><b>${esc(c.razon_social)}</b>${c.nombre_comercial?` (${esc(c.nombre_comercial)})`:''}<div class="disp">${esc(c.ruc)}</div></button>`).join('')||'<div class="p-2 text-muted">No se encontraron clientes.</div>';box.style.display='block'},180)});
document.getElementById('despacho_cliente_resultados').addEventListener('click',e=>{const b=e.target.closest('[data-cliente-index]');if(!b)return;const c=clientesDespachoResultados[Number(b.dataset.clienteIndex)];if(!c)return;despacho_cliente_ruc.value=c.ruc;despacho_cliente_texto.value=c.razon_social;despacho_cliente_seleccionado.textContent=`Seleccionado: ${c.razon_social} (${c.ruc})`;despacho_cliente_resultados.style.display='none'});
document.addEventListener('click',e=>{if(!e.target.closest('.pc-venta-cliente-buscador'))document.getElementById('despacho_cliente_resultados').style.display='none'});
function abrirRegistroClienteDespacho(){document.getElementById('formClienteDespacho').reset();trModalCliente.show();setTimeout(()=>{const backdrops=document.querySelectorAll('.modal-backdrop');const top=backdrops[backdrops.length-1];if(top)top.classList.add('tr-backdrop-cliente');document.getElementById('modalClienteDespacho').style.zIndex='1070'},20)}
document.getElementById('modalClienteDespacho').addEventListener('hidden.bs.modal',()=>{document.getElementById('modalClienteDespacho').style.zIndex='';if(document.getElementById('modalDespacho').classList.contains('show')){document.body.classList.add('modal-open');document.querySelectorAll('.modal-backdrop.tr-backdrop-cliente').forEach(b=>b.remove())}});
document.getElementById('nuevo_cliente_dni').addEventListener('input',function(){this.value=this.value.replace(/\D/g,'')});
document.getElementById('formClienteDespacho').addEventListener('submit',async e=>{e.preventDefault();const ruc=document.getElementById('nuevo_cliente_dni').value.trim(),nombre=document.getElementById('nuevo_cliente_nombre').value.trim();if(!/^\d{8}$|^\d{11}$/.test(ruc)||!nombre){msg('Revisa los datos','Ingresa DNI de 8 dígitos o RUC de 11 dígitos y el nombre.','warning');return}try{const existe=await fetch('controllers/clssProveedor.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({accion:'OBTENERPROVEEDOR',ruc})}).then(r=>r.json());if(existe.success){msg('Cliente ya registrado','Busca el RUC/DNI en el campo Cliente y selecciónalo.','warning');return}const respuesta=await fetch('controllers/clssProveedor.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({accion:'GUARDARPROVEEDOR',ruc,razon_social:nombre,nombre_comercial:document.getElementById('nuevo_cliente_comercial').value.trim(),js_tipo:JSON.stringify(['cliente']),telefonos_contacto:'[]',solo_nuevo_cliente:'1',js_consulta_api:''})}).then(r=>r.json());if(!respuesta.success)throw Error(respuesta.message||'No se pudo registrar el cliente.');trModalCliente.hide();await cargarDatosDespacho();despacho_cliente_ruc.value=ruc;despacho_cliente_texto.value=nombre;despacho_cliente_seleccionado.textContent=`Seleccionado: ${nombre} (${ruc})`;msg('Listo','Cliente registrado y seleccionado.','success')}catch(err){msg('No se pudo registrar',err.message)}});
</script>
